style.css:
@-moz-document url-prefix("https://billing.pars.host/") {
#replyfrm textarea {
    font-family: 'tahoma' !important;
    font-size: 20px !important;
    direction: rtl;
    text-align: right;
}
.message {
    direction: rtl !important;
    font-family: 'tahoma' !important;
}
textarea[name="notes"] {
    direction: rtl;
    text-align: right;
}

.datatable td div {
    text-align: right !important;
}
#ticketreplies .tools {
    visibility: visible !important;
}
#ticketreplies .tools {
    display: block !important;
}
#replymessage {
    font-family: 'tahoma' !important;
    direction: rtl;
    text-align: right;
}
/* جابجایی ترتیب دکمه‌های QC و قرار گرفتن در leftcol */
#ticketreplies .reply .leftcol .n8n-qc-line {
  display: flex !important;
  flex-direction: row-reverse !important;   /* جای دو دکمه عوض می‌شود */
  flex-wrap: wrap !important;
  gap: 6px !important;
  margin-top: 8px !important;
  width: 100% !important;
  clear: both !important;
}

#ticketreplies .reply .leftcol .n8n-qc-inline-btn,
#ticketreplies .reply .leftcol .n8n-qc-report-btn {
  margin: 0 !important;
}
}
